import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.DgVVaeR-.js";const m=JSON.parse('{"title":"ChromeOS / デスクトップ入力","description":"","frontmatter":{},"headers":[],"relativePath":"dev/chromeos.md","filePath":"dev/chromeos.md","lastUpdated":1791090709000}'),d={name:"dev/chromeos.md"};function i(l,e,c,n,h,s){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="chromeos-デスクトップ入力" tabindex="-1">ChromeOS / デスクトップ入力 <a class="header-anchor" href="#chromeos-デスクトップ入力" aria-label="Permalink to &quot;ChromeOS / デスクトップ入力&quot;">​</a></h1><h2 id="対応内容" tabindex="-1">対応内容 <a class="header-anchor" href="#対応内容" aria-label="Permalink to &quot;対応内容&quot;">​</a></h2><ul><li>タッチスクリーン、マルチタッチ、加速度センサー、電話、カメラ、自動フォーカスを必須にしない。バイブレーションは Android のハードウェア機能宣言ではなく、既存の <code>hasVibrator()</code> 判定で非搭載機を扱う。</li><li>Rust の <code>pixiv-api</code> と <code>pallasync-core</code> は既存の <code>cargo ndk -t x86_64</code> で <code>x86_64-linux-android</code> 用にビルドする。Intel / AMD 向けAPKと universal APKに両方の <code>.so</code> を同梱する。速度改善率は実測していない。</li><li>MainActivity は既存の <code>resizeableActivity=&quot;true&quot;</code> と <code>screenSize|smallestScreenSize|screenLayout|orientation</code> の構成変更処理を維持する。固定アスペクト比制限はない。</li></ul><h2 id="キーボード" tabindex="-1">キーボード <a class="header-anchor" href="#キーボード" aria-label="Permalink to &quot;キーボード&quot;">​</a></h2><table tabindex="0"><thead><tr><th>キー</th><th>操作</th></tr></thead><tbody><tr><td>Ctrl+F</td><td>検索欄を展開してフォーカス。検索結果表示中は検索画面を重ねない</td></tr><tr><td>Ctrl+R / F5</td><td>現在のフィード・ランキング・ブックマーク・検索結果・詳細・小説を再読み込み。画像ビューアでは画像キャッシュを読み飛ばして再取得</td></tr><tr><td>Esc</td><td>Androidの戻る処理で最前面のモーダル・シート・ビューアを閉じる</td></tr><tr><td>Ctrl+W</td><td>画像ビューア・保存済みビューア・小説リーダーを閉じる</td></tr><tr><td>← / →、Shift+Space / Space</td><td>画像ビューア・小説リーダーの前後ページへ移動。音量キー設定とは独立</td></tr><tr><td>Ctrl+S</td><td>画像ビューアの現在ページの原寸画像を通常の保存キューへ追加</td></tr><tr><td>F</td><td>画像ビューア・小説リーダーの全画面閲覧を切り替え</td></tr><tr><td>J / K</td><td>小説の次・前の段落へスクロール。横書き・連続表示・縦書きに対応</td></tr></tbody></table><p>設定画面など、再取得対象のない画面では更新キーでホームを更新しない。音量キーのページ送りは既存設定に従う。</p><h2 id="マウス・トラックパッド" tabindex="-1">マウス・トラックパッド <a class="header-anchor" href="#マウス・トラックパッド" aria-label="Permalink to &quot;マウス・トラックパッド&quot;">​</a></h2><p>作品カードにハンドカーソルと軽いホバー拡大を適用する。右クリックは専用メニューを開き、タッチ長押しのQuickPeekを維持する。</p><p>メニューにはブラウザーの新しいタブで開く、画像コピー、非公開ブックマーク追加、別名で保存がある。アプリ内の複数タブではなく外部ブラウザーのタブを使う。既にブックマーク済みの場合は非公開追加を表示しない。別名保存はAndroidのドキュメント作成画面で保存先・ファイル名を選び、複数ページ作品は先頭ページを保存する。</p><p>ChromeOSの標準入力変換で届く2点ピンチは既存の列数変更処理に接続する。Ctrl+ホイールも同じ設定・列数範囲に従う。通常の2本指スクロールとホイールはスクロールとして扱う。2本目の指が接触したイベントをInitialパスで消費し、列数変更の閾値に達する前にカードの長押し判定をキャンセルする。1本だけ残った場合も全て離すまでイベントを消費し、QuickPeekやクリックへの誤遷移を防ぐ。</p><h2 id="最小化中の処理" tabindex="-1">最小化中の処理 <a class="header-anchor" href="#最小化中の処理" aria-label="Permalink to &quot;最小化中の処理&quot;">​</a></h2><p>TTSは既存のmediaPlayback Foreground Service、MediaSession、音声フォーカスを使用し、Compose UIの破棄では再生を終了しない。</p><p>画像保存にはdataSync Foreground Serviceを追加する。待機中を含む保存処理を参照カウントで保護し、最後の処理の終了・失敗・キャンセルでサービスとWakeLockを解放する。別名保存も同じ保護を使用する。WakeLockには上限を設け、AndroidのdataSyncタイムアウトではサービスを停止する。OSによる強制終了、通信断、dataSyncの実行時間制限を超えた永続的再開は保証しない。</p><h2 id="実機確認手順" tabindex="-1">実機確認手順 <a class="header-anchor" href="#実機確認手順" aria-label="Permalink to &quot;実機確認手順&quot;">​</a></h2><ol><li>タッチ非搭載のx86_64 ChromeOSでインストールし、ログインと画像・小説取得を確認する。</li><li>各タブでCtrl+R / F5を押し、当該タブだけが更新されることを確認する。</li><li>Ctrl+Fを繰り返し、検索語を直接入力できることを確認する。</li><li>複数ページ画像の横読み・縦読みでページ送りとCtrl+Sを確認する。テキスト入力中のSpaceが入力を妨げないことも確認する。</li><li>小説の全レイアウトでJ / Kを確認し、目次・設定シートではEscが先にシートを閉じることを確認する。</li><li>右クリック、ホバー、タッチ長押し、ピンチ、Ctrl+ホイール、通常スクロールを比較する。</li><li>ウィンドウを連続リサイズし、位置・検索語・再生状態が保持されることを確認する。</li><li>TTSと複数ダウンロードを開始して最小化し、通知の再生操作、保存完了、最後の保存後の通知終了を確認する。</li></ol><p>参考: <a href="https://developer.android.com/develop/devices/chromeos/learn/manifest" target="_blank" rel="noreferrer">AndroidのChromeOSマニフェスト互換性</a>、<a href="https://developer.android.com/develop/devices/chromeos/learn/input-compatibility" target="_blank" rel="noreferrer">入力互換性</a>。</p><h2 id="操作の回帰修正" tabindex="-1">操作の回帰修正 <a class="header-anchor" href="#操作の回帰修正" aria-label="Permalink to &quot;操作の回帰修正&quot;">​</a></h2><p>詳細画面のハートは、空のクリックを持つFABと外側のcombinedClickableを重ねず、共通のBookmarkHeartButtonでタップと長押しを一括処理する。非公開成功アニメーションはブックマーク済み状態がAPI応答で更新された後に表示する。ブックマーク成功後の任意の自動フォロー等が失敗しても、成功済みのブックマーク状態を画面へ反映する。</p>',18)])])}const u=t(d,[["render",i]]);export{m as __pageData,u as default};
